"use strict";const NON_FILTER_PARAMETERS=new Set(["csrfmiddlewaretoken","page"]);function findFilterForm(){const t=document.querySelector(".submit-filter");return t?t.form||t.closest("form"):document.querySelector("form")}function isUnsetSelect(t){return t.tagName==="SELECT"&&!t.multiple&&t.value==="unknown"}function isNonFilterControl(t){return NON_FILTER_PARAMETERS.has(t.name)||t.value===""||isUnsetSelect(t)}function filterControlEntries(t){const n=[];for(const e of t.elements)if(!(!e.name||e.disabled)&&!(e.type==="submit"||e.type==="button"||e.type==="reset")){if(e.tagName==="SELECT"&&e.multiple){for(const o of e.selectedOptions)o.value!==""&&n.push([e.name,o.value]);continue}if(e.type==="checkbox"||e.type==="radio"){e.checked&&n.push([e.name,e.value]);continue}isNonFilterControl(e)||n.push([e.name,e.value])}return n}function parseFilterParameters(){const t=findFilterForm();return t?new URLSearchParams(filterControlEntries(t)):(console.warn("No form found on the page. Returning an empty URLSearchParams object."),new URLSearchParams)}function initFilterFormCleanup(){document.querySelectorAll(".submit-filter").forEach(t=>{const n=t.form||t.closest("form");n&&n.method==="get"&&n.addEventListener("submit",e=>{e.preventDefault();const o=new URLSearchParams(filterControlEntries(n)).toString(),r=n.getAttribute("action")||window.location.pathname;window.location.href=o?`${r}?${o}`:r})})}document.addEventListener("DOMContentLoaded",initFilterFormCleanup);function lockFilter(){document.querySelectorAll(".submit-filter").forEach(n=>{n.value="Loading...",n.textContent="Loading...",n.disabled=!0})}function lockCustomElements(){}function unlockFilter(){document.querySelectorAll(".submit-filter").forEach(n=>{n.value="Filter",n.textContent="Filter",n.disabled=!1})}function unlockCustomElements(){}function clickedFilterButton(){lockFilter()}
